import{_ as s,l as n,o as e,c as l,v as t,p as i,x as o,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"大页","description":"","frontmatter":{"title":"大页","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/huge-pages.md","filePath":"cs/huge-pages.md","lastUpdated":1789023840000}'),c={name:"cs/huge-pages.md"};function B(u,a,A,m,E,_){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="大页" tabindex="-1">大页 <a class="header-anchor" href="#大页" aria-label="Permalink to &quot;大页&quot;">​</a></h1><div class="epigraph"><p>用 2MB 或 1GB 的页覆盖同一段虚区间，TLB 里一条就能翻译许多 4K 页曾经占用的项。</p><footer>—— 据 Hennessy and Patterson, Computer Architecture: A Quantitative Approach；Navarro 等对超级页的整理</footer></div><p><a href="/cs/page-fault-path">上一课</a>按 4K 补页。<a href="/cs/tlb-translate">TLB</a> 条目有限：工作集一宽，翻译缺失比数据缺失更先爆。<a href="/cs/paging-vm">分页</a>允许页大小是 2 的幂，硬件用页表中间层的「叶子」指向大块物理内存。缺口是<strong>何时用大页</strong>：减 TLB 压力，而不把按需策略推倒重来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>数据库缓冲池、虚拟机客户内存、科学计算数组，往往是连续 GB 级。若全用 4K，TLB 覆盖范围只有「项数 × 4K」。缺口不是新的 MMU 周期公式，而是：内核把若干连续物理页合成更大粒度，页表少走一层，TLB 以大页标签命中。代价是内碎片、分配失败时的回退，以及缺页一次要填的块变大。</p><p>本课不把每代 x86 的 PSE/PDPE 控制位写成手册。</p><p><span class="marginnote">透明大页（THP）在运行中折叠或拆开；显式 <code>mmap</code>/<code>hugetlbfs</code> 由程序申请。折叠需要连续物理内存，与后课 buddy 的高阶块相关。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>硬件：某级页表项置「大页」位，该项的物理基址对齐到 2MB/1GB，偏移字段变长。<a href="/cs/page-fault-path">缺页路径</a>若决定用大页，一次分配整块并填一项。用户可 <code>madvise</code> 提示；也可映射 hugetlbfs。失败则退回 4K，正确性不变，只是 TLB 覆盖变差。</p>',9)),(e(),i(h,null,{default:o(()=>[p(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20WS%5B%22%E5%A4%A7%E5%9D%97%E8%BF%9E%E7%BB%AD%E5%B7%A5%E4%BD%9C%E9%9B%86%22%5D%20--%3E%20HP%5B%22%E5%A4%A7%E9%A1%B5%3A%20%E4%B8%80%E9%A1%B9%E8%A6%86%E7%9B%96%22%5D%0A%20%20WS%20--%3E%20BASE%5B%224K%3A%20%E5%A4%9A%E9%A1%B9%E5%8D%A0%E6%BB%A1%20TLB%22%5D%0A%20%20HP%20--%3E%20TLB%5B%22TLB%20%E5%91%BD%E4%B8%AD%E7%8E%87%E5%8D%87%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>大页把局部性从「页内」扩到「段内」：顺序扫描 2MB 不再换 512 条 4K 翻译。它不改变用户/内核分裂，也不取消按需——可以按大页粒度按需。与 Cache 行无关：大页不是把 Cache 变大，只是翻译变粗。</p><p>多核上拆大页或改权限，要冲掉的 TLB 项更「宽」，下一课 shootdown 会更疼。本课只承认粒度变了。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证大页降低每一种负载：指针追逐、稀疏堆可能浪费物理内存。也不把设备 DMA 对齐问题写完。交换大页要拆或整块写出，实现复杂，主干留到 swap 课点名。不要在此重导多级页表。</p><p>后课默认：翻译项可以覆盖 2MB 级块。改页表后其他 CPU 的 TLB 如何作废，下一课 TLB shootdown。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>大页用更少 TLB 项覆盖连续工作集。</li><li>按需仍在，只是分配粒度变大；可回退 4K。</li><li>多核作废翻译是 shootdown 的缺口。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em>；Navarro et al., superpages；Tanenbaum <em>MOS</em>。</li></ul>',8))])}const g=s(c,[["render",B]]);export{f as __pageData,g as default};
